func newTimesheet() unsafe.Pointer { return unsafe.Pointer(new(timesheet.Timesheet)) }

func newNTimesheet(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]timesheet.Timesheet, n)))
}

func ptrTimesheet(p unsafe.Pointer, c int32) any {
	r := (*timesheet.Timesheet)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Status))
	case 5:
		return &r.PeriodStart
	case 6:
		return &r.PeriodEnd
	case 7:
		return &r.RegularMinutes
	case 8:
		return &r.OvertimeMinutes
	case 9:
		return &r.PaidLeaveMinutes
	case 10:
		return &r.EntryCount
	case 11:
		return &r.OvertimeThresholdMinutes
	case 12:
		return &r.SubmittedAt
	case 13:
		return (*string)(unsafe.Pointer(&r.SubmittedByID))
	case 14:
		return &r.ApprovedAt
	case 15:
		return (*string)(unsafe.Pointer(&r.ApprovedByID))
	case 16:
		return &r.DecisionNote
	case 17:
		return (*string)(unsafe.Pointer(&r.PayrollExportID))
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueTimesheet(p unsafe.Pointer, c int32) any {
	r := (*timesheet.Timesheet)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		return string(r.Status)
	case 5:
		return r.PeriodStart
	case 6:
		return r.PeriodEnd
	case 7:
		return r.RegularMinutes
	case 8:
		return r.OvertimeMinutes
	case 9:
		return r.PaidLeaveMinutes
	case 10:
		return r.EntryCount
	case 11:
		return r.OvertimeThresholdMinutes
	case 12:
		if r.SubmittedAt == nil {
			return nil
		}
		return *r.SubmittedAt
	case 13:
		if r.SubmittedByID == "" {
			return nil
		}
		return string(r.SubmittedByID)
	case 14:
		if r.ApprovedAt == nil {
			return nil
		}
		return *r.ApprovedAt
	case 15:
		if r.ApprovedByID == "" {
			return nil
		}
		return string(r.ApprovedByID)
	case 16:
		if r.DecisionNote == "" {
			return nil
		}
		return r.DecisionNote
	case 17:
		if r.PayrollExportID == "" {
			return nil
		}
		return string(r.PayrollExportID)
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

func attachTimesheet(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*timesheet.Timesheet)(p)
	switch rel {
	case 0:
		r.Worker = (*worker.Worker)(child)
	}
}

func beforeCreateTimesheet(ctx context.Context, p unsafe.Pointer) error {
	return (*timesheet.Timesheet)(p).BeforeCreate(ctx)
}

func init() {
	timeClockEntriesTable.Relations[0].Target = workerdb.WorkersSchema()
	timesheetsTable.Relations[0].Target = workerdb.WorkersSchema()
}

var enumPayrollExportStatus = [...]schema.EnumValue{
	{Value: `Draft`, Label: `Payroll Export Draft`},
	{Value: `Generated`, Label: `Payroll Export Generated`},
	{Value: `Voided`, Label: `Payroll Export Voided`},
}

var enumTimeEntrySource = [...]schema.EnumValue{
	{Value: `Clock`, Label: `Clock`},
	{Value: `Portal`, Label: `Portal`},
	{Value: `Manual`, Label: `Manual`},
	{Value: `Import`, Label: `Import`},
}

var enumTimesheetStatus = [...]schema.EnumValue{
	{Value: `Open`, Label: `Timesheet Open`, Doc: `TimesheetOpen is a week still being worked or corrected.`},
	{Value: `Submitted`, Label: `Timesheet Submitted`, Doc: `TimesheetSubmitted is a week handed to a manager. Its totals are frozen from here on: they are what the manager is being asked to approve.`},
	{Value: `Approved`, Label: `Timesheet Approved`},
	{Value: `Rejected`, Label: `Timesheet Rejected`, Doc: `TimesheetRejected goes back to Open so the entries can be corrected.`},
	{Value: `Locked`, Label: `Timesheet Locked`, Doc: `TimesheetLocked is a week that has gone to payroll. Nothing about it changes again unless the export is voided.`},
}

